# yaml-language-server: $schema=./gate.schema.json
# gate.yaml -- code-forge configuration
# Generated by: code-forge init

# outlet: review dispatch method
#   subprocess (default) -- spawns a fresh subprocess per review pass.
#                           Requires a backend under 'backends:' below.
#   inline              -- review runs in the current session (uses main quota).
#                           No subprocess, no reachability probe.
#   subagent            -- spawns a fresh Agent per pass; works inside the current
#                           session without a subprocess.
#   sampling            -- MCP only: borrows the IDE client's model, no API key.
# Note: 'cli' is a deprecated alias for 'subprocess' (emits a stderr warning).
# subprocess fails closed until a backend is configured under 'backends:'.
outlet: subprocess

# Cycle count adapts to diff size (relief, not defense):
#   <50 lines:  2 clean cycles (6 passes)
#   50-199:     3 clean cycles (9 passes, default)
#   >=200:      4 clean cycles (12 passes)
# Override: FORGE_CLEAN_ROUND_THRESHOLD=N

# backends: named review backends, keyed by name (dict, not list).
