# test: test command run by code-forge gate-check (R1 commit gate).
# Without this section, gate-check exits with an error.
# test:
#   command: [pytest, -q]         # required: list form, first element must be a known runner
#   timeout_seconds: 120          # optional: integer > 0 (default: 120)
#   env: {}                       # optional: extra env vars dict (omit = inherit shell env)
#   cwd: .                        # optional: working directory string (omit = repo root)
#   source_patterns: ["*.py"]     # optional: list of globs; gate skips if no staged file matches

# non_ascii: non-ASCII detection mode for commit messages and diffs.
#   ai-smell (default) -- blocks confusable typographic characters only
#                         (em dash, smart quotes, ellipsis, right arrow, NBSP).
#                         Accented letters, CJK, and emoji pass.
#   strict              -- blocks every non-ASCII byte.
# non_ascii: ai-smell

# presubmit: external linters run on staged diffs before the test gate.
# Each entry is run on the diff for files matching applies_to.
# presubmit:
#   - command: [ruff, check, --select=E,W]  # required: list form
#     applies_to: "*.py"                     # required: glob pattern
#     on: diff                               # required: 'diff' or 'patch'
#     when_exists: pyproject.toml            # optional: skip entry if this file is absent

# graph_triage: code-review-graph integration for impact-aware triage.
# graph_triage:
#   enabled: true                # optional: bool (omit = auto-detected)
#   db_path: .code-review-graph/graph.db  # optional: override graph.db path

# daemon_state: stateful subsystem conflict detection.
# daemon_state:
#   enabled: true                # optional: bool (omit = disabled)
#   subsystems: [networking]     # optional: state domains to focus on
#   patterns: []                 # optional: extra keyword patterns
#   conflicts_file: .code-forge/conflicts.yaml  # optional: external conflict triplets
#   conflicts:                   # optional: inline conflict triplets
#     - subsystem: networking    # required per triplet
#       mutates: routing_table   # required per triplet
#       interferes_with: firewall_rules  # required per triplet

# canary: opt-in reviewer laziness check (plants known-bad mutations).
# canary:
#   enabled: true
#   n: 5                    # canaries to plant (3..5)
#   threshold_ratio: 0.6   # catch ratio to pass (>0.0..1.0)
